package m8

import "net/http"

func (h *Hub) HandleClarificationPage(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("X-Frame-Options", "DENY")
	_, _ = w.Write([]byte(specClarificationHTML))
}

const specClarificationHTML = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spec 解释与补充</title>
<style>body{font:16px/1.6 system-ui,sans-serif;background:#f5f7fb;color:#192a40;overflow-wrap:anywhere;max-width:960px;margin:0 auto;padding:16px}*{box-sizing:border-box}header,.row{display:flex;flex-wrap:wrap;gap:12px;align-items:center}h1{font-size:24px}h2{font-size:20px}section,article{background:white;padding:16px;border:1px solid #d7deeb;border-radius:8px;margin:16px 0;min-width:0}label{display:block;margin:12px 0}input,select,textarea,button{font:inherit;min-height:44px;padding:10px;border:1px solid #8e9db5;border-radius:5px;max-width:100%}input,textarea,select{width:100%}textarea{min-height:128px;resize:vertical}button,a.touch{min-width:44px;min-height:44px;display:inline-flex;align-items:center;cursor:pointer}button{background:#edf3ff}a{color:#1554a2;overflow-wrap:anywhere}pre,.body{white-space:pre-wrap;overflow-wrap:anywhere}.excerpt{max-height:320px;overflow:auto}.muted{color:#4a607d}.authority{font-weight:bold}.technical{border-left:5px solid #8493a8}.deputy{border-left:5px solid #bf7918}#status{white-space:pre-wrap;overflow-wrap:anywhere}[hidden]{display:none!important}@media(max-width:600px){body{padding:12px}header{align-items:flex-start}h1{font-size:22px}section,article{padding:12px}.row>*{flex:1 1 auto}}</style>
<header><a class="touch" href="/console/questions">研发问题</a><h1>Spec 解释与补充</h1></header>
<p>① 看对应条目　② 解释或提出变更　③ 核对入帖楼号</p><p class="muted">定稿正文不改。权威解释仅来自 PM 或事先指定的代答；技术说明不构成授权、完成或业务签收。</p><p class="muted">飞书内置浏览器若无法登录，请从右上角菜单选择外部浏览器打开同一链接；仍需本人登录，链接不携带身份。</p><p id="status" role="status" aria-live="polite"></p>
<section id="question" hidden><h2 id="title"></h2><p id="version"></p><div id="excerpt" class="body excerpt" tabindex="0" aria-label="问题摘要"></div><p id="role"></p><div class="row"><a class="touch" id="spec-link">查看 Spec 只读原文</a><a class="touch" id="change-link">需改 Spec：进入后继修订流程</a></div></section>
<section id="policy" hidden><h2>PM 与代答人</h2><form id="policy-form"><label>PM 平台用户 ID<input id="pm" autocomplete="off" maxlength="128"></label><label>唯一代答人 ID（由 PM 指定，可留空）<input id="deputy" autocomplete="off" maxlength="128"></label><p class="muted">代答先在 Console 回复；飞书仅接 PM 本人。撤销立即影响后续写入，不更改历史身份。</p><button>保存当前政策</button></form></section>
<section id="compose" hidden><h2>追加回复</h2><form id="reply-form"><label>类型<select id="kind"></select></label><label>条目／子例 ID（多个用逗号分隔）<input id="refs" maxlength="3000" required list="known-refs"></label><datalist id="known-refs"></datalist><p id="anchor-hint" class="muted"></p><label id="target-label" hidden>更正或追认第几条<input id="target" type="number" min="1" step="1"></label><label id="reason-label" hidden>更正理由<input id="reason" maxlength="600"></label><label>正文<textarea id="body" maxlength="2400" required></textarea></label><label>证据引用（可留空，显示未提供）<input id="evidence" maxlength="600"></label><label>可选附图（PNG／JPEG／WebP，最多4张、每张5 MiB；不得含凭据或源码）<input id="images" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><p id="image-status" class="muted"></p><p id="scope-hint" class="muted">解释不改范围；影响需求、验收或约束时，必须选“需改 Spec”留下变更提案，后继修订生效前不改变原任务门。</p><div class="row"><button id="submit">追加并核对楼号</button><button id="lookup" type="button">核对上一笔结果</button></div></form></section>
<section><h2>追加楼层</h2><p class="muted">更正通过新楼层指向原楼层；不会覆盖、删除旧正文。旧 D3 历史仍在原问题页，标为未核权威的历史答复。</p><div id="posts"></div><div class="row"><button id="refresh" type="button">刷新最新楼层</button><button id="older" type="button" hidden>更早楼层</button></div></section>
<script>
'use strict';const $=id=>document.getElementById(id),qid=new URLSearchParams(location.search).get('question_id')||'',base='/api/console/questions/'+encodeURIComponent(qid)+'/clarifications';let current=null,policy=null,before=0,busy=false,pending=null,key='',uploaded=[],imageBusy=false;
function say(s){$('status').textContent=s}
function clearPrivate(){current=null;policy=null;$('posts').replaceChildren();for(const id of ['question','compose','policy'])$(id).hidden=true;uploaded=[];$('images').value='';for(const id of ['body','refs','target','reason','evidence','pm','deputy'])$(id).value='';for(const id of ['title','version','excerpt','role'])$(id).textContent=''}
function loadPending(){try{const raw=localStorage.getItem(key);pending=raw?JSON.parse(raw):null}catch(_){pending=null}if(pending&&pending.data){const d=pending.data;$('kind').value=d.kind;$('refs').value=(d.entry_refs||[]).join(',');$('body').value=d.body||'';$('evidence').value=d.evidence_ref||'';$('target').value=d.corrects||d.confirms||'';$('reason').value=d.reason||'';uploaded=d.file_ids||[];say('上一笔结果待确认；保留原提交标识，先核对结果或用原内容重试。')}}
async function api(path,options,optional=false){let r;try{r=await fetch(path,{credentials:'same-origin',cache:'no-store',...options})}catch(_){throw Object.assign(new Error('网络中断：结果待确认，保留原提交标识，不另发一笔。'),{unknown:true})}let b={};try{b=await r.json()}catch(_){}if(r.status===401){clearPrivate();throw new Error('请重新登录后返回此问题；链接不是登录凭据。')}if(r.status===403){if(!optional)clearPrivate();throw new Error('当前身份或问题权限已失效。')}if(!r.ok)throw Object.assign(new Error(r.status===409?'政策、范围或提交内容冲突，请刷新核对。':r.status===429?'本问题回复达到频率或总量上限，请稍后或联系 PM。':r.status===503?'当前写入未启用或结果待确认，请核对原提交。':r.status===404?'尚未查到入帖结果；只能沿原提交标识重试。':'明确未入帖：请核对类型、锚点与引用楼号。'),{unknown:r.status>=500,notFound:r.status===404});return b}
function appendPost(p){const a=document.createElement('article');a.id='floor-'+p.floor;a.className=p.role;const h=document.createElement('p');h.className='authority';h.textContent='第 '+p.floor+' 条 · '+(p.role==='pm'?'PM':p.role==='deputy'?'代答，PM未追认':'技术说明（非权威）')+' · '+p.actor+' · '+p.created_at;const body=document.createElement('div');body.className='body';body.textContent=p.body;const meta=document.createElement('p');meta.className='muted';meta.textContent='锚点：'+(p.entry_refs||[]).join('、')+'；证据：'+(p.evidence_ref||'未提供证据');a.append(h,body,meta);for(const f of p.images||[]){const link=document.createElement('a');link.className='touch';link.href='/api/console/questions/'+encodeURIComponent(p.question_id)+'/clarification-images/'+encodeURIComponent(f.file_id);link.target='_blank';link.rel='noopener noreferrer';link.textContent='查看私有附图（需当前问题权限）';a.append(link)}for(const [n,label] of [[p.corrects,'更正'],[p.confirms,'PM追认'],[p.previous_floor,'补充，前一条']])if(n){const link=document.createElement('a');link.className='touch';link.href='#floor-'+n;link.textContent=label+'第 '+n+' 条';a.append(link)}if(p.kind==='scope_change'){const note=document.createElement('p');note.textContent='变更提案，尚未生效：须走 D1 后继修订与所有者确认。';a.append(note)}$('posts').append(a)}
function setKind(){const k=$('kind').value;$('target-label').hidden=k!=='correction'&&k!=='confirmation';$('reason-label').hidden=k!=='correction';$('target').required=k==='correction'||k==='confirmation';$('reason').required=k==='correction';$('scope-hint').textContent=k==='scope_change'?'这会留下待确认变更提案，不能用一句话批准新范围。请继续完成后继修订。':'解释不改范围；技术说明非权威；回复到件不代表任务恢复或签收。'}
async function loadPolicy(){try{const b=await api('/api/console/specs/'+encodeURIComponent(current.spec_id)+'/clarification-policy',undefined,true);policy=b.policy;$('pm').value=policy.pm_user||'';$('pm').disabled=!b.can_select_pm;$('deputy').value=policy.deputy_user||'';$('deputy').disabled=!b.can_select_deputy;$('policy').hidden=!b.enabled}catch(e){if(!current)return;/* A thread grant alone need not grant policy management. */}}
async function load(older=false){if(!qid){say('请从具体问题的通知或任务链接进入。');return}const b=await api(base+(older&&before?'?before='+before:''));current=b.context;key='dw-clarification-pending-v1:'+current.actor+':'+qid;if(!older){$('posts').replaceChildren();$('title').textContent=current.title;$('version').textContent='Spec '+current.spec_id+' · 修订 '+current.revision+' · SHA '+current.content_sha256;$('excerpt').textContent=current.question+'\n期待：'+current.expected_answer;$('role').textContent=current.role==='pm'?'当前以 PM 身份回答':current.role==='deputy'?'当前为预指定代答人：答复须标明代答':'当前只能补技术说明，不能作权威解释';$('question').hidden=false;$('compose').hidden=!b.enabled||current.archived;$('spec-link').href='/console/specs/'+encodeURIComponent(current.spec_id)+'?clarification_readonly=1';$('change-link').href='/console/spec-templates?predecessor_spec_id='+encodeURIComponent(current.spec_id);const selected=$('kind').value;$('kind').replaceChildren();const options=current.role==='technical'?[['technical','技术说明（非权威）']]:[['explanation','解释（不改范围）'],['scope_change','需改 Spec（待确认提案）'],['correction','更正先前楼层'],...(current.role==='pm'?[['confirmation','PM追认代答']]:[]),['technical','技术说明（非权威）']];for(const [v,label]of options){const o=document.createElement('option');o.value=v;o.textContent=label;$('kind').append(o)}if(options.some(x=>x[0]===selected))$('kind').value=selected;$('known-refs').replaceChildren();for(const id of current.entry_refs||[]){const o=document.createElement('option');o.value=id;$('known-refs').append(o)}if(!$('refs').value&&current.entry_refs&&current.entry_refs.length)$('refs').value=current.entry_refs[0];$('anchor-hint').textContent=current.anchors_truncated?'仅列出前300个锚点；其他条目可按原文ID填写，服务端仍核对原版本。':'请选择原版本已有条目或子例，不以回复改写定稿。';setKind()}for(const p of b.posts||[])appendPost(p);before=b.next_before||0;$('older').hidden=!before}
async function lookup(){if(!pending){say('没有结果待核对的提交。');return}try{const b=await api(base+'/requests/'+encodeURIComponent(pending.data.request_id));localStorage.removeItem(key);pending=null;uploaded=[];$('images').value='';say('已入第 '+b.post.floor+' 条；没有重复新增。');try{await load()}catch(e){say('已入第 '+b.post.floor+' 条；'+e.message)}}catch(e){say(e.message)}}
$('images').onchange=async()=>{if(pending){$('images').value='';say('上一笔结果未知，不能替换附图；请先核对原提交。');return}uploaded=[];const files=Array.from($('images').files);if(files.length>4||files.some(f=>f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type))){$('images').value='';say('附图未上传：最多4张，每张5 MiB，仅PNG/JPEG/WebP。');return}imageBusy=true;$('submit').disabled=true;try{for(const file of files){const r=await fetch('/api/console/questions/'+encodeURIComponent(qid)+'/clarification-images',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:file});if(!r.ok)throw new Error('附图未完成；可能是私有文件服务待配置、权限失效或文件不合要求，不会作为成功附件入帖。');const b=await r.json();uploaded.push(b.image.file_id)}$('image-status').textContent='已完成 '+uploaded.length+' 张私有附图上传，追加回复后才关联楼层。'}catch(e){uploaded=[];$('image-status').textContent=e.message}finally{imageBusy=false;$('submit').disabled=false}};
$('kind').onchange=setKind;$('lookup').onclick=lookup;$('refresh').onclick=()=>load().catch(e=>say(e.message));$('older').onclick=()=>load(true).catch(e=>say(e.message));
$('reply-form').onsubmit=async e=>{e.preventDefault();if(busy||imageBusy||!current)return;if($('images').files.length&&uploaded.length!==$('images').files.length){say('附图尚未全部上传成功，明确未提交；重选附图或清空后再提交。');return}const d={kind:$('kind').value,entry_refs:$('refs').value.split(',').map(s=>s.trim()).filter(Boolean),body:$('body').value,evidence_ref:$('evidence').value,...(uploaded.length?{file_ids:uploaded}:{} )};if(d.kind==='correction'){d.corrects=Number($('target').value);d.reason=$('reason').value}if(d.kind==='confirmation')d.confirms=Number($('target').value);const logical=JSON.stringify(d);if(pending&&pending.logical!==logical){say('上一笔结果未知，不能换内容或新标识；请先核对原笔结果。');return}if(!pending){pending={logical,data:{...d,request_id:crypto.randomUUID()}};try{localStorage.setItem(key,JSON.stringify(pending))}catch(_){pending=null;say('无法保存弱网提交标识，本次明确未提交；请允许此站点本地存储后重试。');return}}busy=true;$('submit').disabled=true;say('提交中，请等待明确入帖楼号。');try{const b=await api(base,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pending.data)});localStorage.removeItem(key);pending=null;uploaded=[];$('images').value='';say('已入第 '+b.post.floor+' 条'+(b.replayed?'（同ID回执，没有重复新增）':'')+'；不代表任务恢复或签收。');try{await load()}catch(e){say('已入第 '+b.post.floor+' 条；'+e.message)}}catch(e){if(!e.unknown&&!e.notFound){localStorage.removeItem(key);pending=null}say(e.message)}finally{busy=false;$('submit').disabled=false}};
$('policy-form').onsubmit=async e=>{e.preventDefault();if(!policy)return;try{const b=await api('/api/console/specs/'+encodeURIComponent(current.spec_id)+'/clarification-policy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_version:policy.version,pm_user:$('pm').value,deputy_user:$('deputy').value})});policy=b.policy;await load();await loadPolicy();say('政策已保存，仅影响后续身份，不改写旧楼层。')}catch(e){say(e.message)}};
(async()=>{try{await load();loadPending();setKind();await loadPolicy()}catch(e){say(e.message)}})();
</script></html>`
